from __future__ import annotations
import html,re
from pathlib import Path
from .core import RUN,Story
W,H=1920,1080
TEXT="#F4F6F8";MUTED="#9FA9B4";ACCENT="#E8B44A";PANEL="#0B1016";LINE="#2B3540"

def _has_arabic(value:str)->bool:return bool(re.search(r"[\u0600-\u06ff]",str(value)))
def _safe(value:str,limit:int=120)->str:return html.escape(str(value)[:limit])
def _text(value,x,y,size=28,weight=600,anchor="start",fill=TEXT)->str:
    value=_safe(value,150);rtl=' direction="rtl" unicode-bidi="plaintext"' if _has_arabic(value) else ""
    return f'<text x="{x}" y="{y}" font-family="Noto Sans Arabic,Noto Sans,DejaVu Sans,sans-serif" font-size="{size}px" font-weight="{weight}" text-anchor="{anchor}" fill="{fill}"{rtl}>{value}</text>'

def _kind(scene)->str:
    text=(str(scene.narration)+" "+str(scene.visual_intent)+" "+" ".join(map(str,scene.callouts))).casefold(); groups={"interior":["interior","cabin","seat","dashboard","screen","مقصورة","داخلية","مقاعد","شاشة","تابلوه"],"safety":["safety","brake","airbag","collision","أمان","فرامل","وسادة","تصادم"],"charging":["charging","charge","شحن","الشحن"],"efficiency":["range","efficiency","consumption","battery","electric","مدى","كفاءة","استهلاك","بطارية","كهربائية"],"technology":["technology","tech","software","sensor","camera","assist","تقنية","تقنيات","حساس","كاميرا","مساعدة"],"design":["design","exterior","body","style","aerodynamic","تصميم","هيكل","شكل","خارجية","ديناميكية"],"performance":["performance","power","horsepower","torque","acceleration","speed","أداء","قوة","حصان","عزم","تسارع","سرعة"],"price":["price","cost","value","سعر","تكلفة","قيمة"]}
    for name,words in groups.items():
        if any(w in text for w in words):return name
    return "hero"

def _family(scene,kind:str)->str:
    plan=("front_3q","low_angle","front_close","rear_3q","wide_scene","three_quarter_high","side_profile","rear_close","design_detail","aero","wheel_detail","interior","technology","safety","battery","charging","performance","comparison","front_3q","low_angle","design_detail","technology","safety","battery","rear_3q")
    return plan[(int(scene.id)-1)%len(plan)]

def _motion(family:str,scene_id:int)->str:return ("push_in","pull_out","orbit_left","orbit_right","rack_focus","tracking","rise")[(scene_id+len(family))%7]
def _defs()->str:return '''<defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#18212B"/><stop offset=".46" stop-color="#080B10"/><stop offset="1" stop-color="#1B1309"/></linearGradient><linearGradient id="body" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FBFCFD"/><stop offset=".20" stop-color="#D6DDE3"/><stop offset=".43" stop-color="#65727E"/><stop offset=".72" stop-color="#26313A"/><stop offset="1" stop-color="#0B1015"/></linearGradient><linearGradient id="glass" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#5D7588"/><stop offset=".42" stop-color="#111D27"/><stop offset="1" stop-color="#050A0F"/></linearGradient><radialGradient id="halo"><stop offset="0" stop-color="#F1C86E" stop-opacity=".30"/><stop offset="1" stop-color="#F1C86E" stop-opacity="0"/></radialGradient><linearGradient id="road" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1D2630"/><stop offset="1" stop-color="#030405"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="18"/></filter></defs>'''
def _environment(scene_id:int)->str:
    offset=(scene_id%4)*70;return f'''<rect width="1920" height="1080" fill="url(#bg)"/><ellipse cx="{900+offset}" cy="540" rx="860" ry="430" fill="url(#halo)"/><path d="M0 840 Q420 690 920 790 T1920 730 V1080 H0 Z" fill="url(#road)"/><path d="M0 900 Q480 760 960 850 T1920 790" fill="none" stroke="#2F3944" stroke-width="4"/><g opacity=".20">{''.join(f'<path d="M{x} 155 L{x-140} 830" stroke="#70808C" stroke-width="2"/>' for x in range(120+offset,1900,260))}</g>'''
def _wheel(cx,cy,r=110)->str:
    spokes=''.join(f'<path d="M{cx} {cy-r+34} L{cx} {cy+r-34}" stroke="#B7C1C8" stroke-width="4" transform="rotate({a} {cx} {cy})"/>' for a in (0,60,120));return f'<g><circle cx="{cx}" cy="{cy}" r="{r}" fill="#050709" stroke="#D6DEE4" stroke-width="10"/><circle cx="{cx}" cy="{cy}" r="{r-26}" fill="#8C98A3"/><circle cx="{cx}" cy="{cy}" r="{r-45}" fill="#11171D" stroke="#53606B" stroke-width="5"/><circle cx="{cx}" cy="{cy}" r="17" fill="{ACCENT}"/>{spokes}</g>'
def _car(transform:str="",wheel_scale:float=1.0)->str:
    return f'''<g transform="{transform}" data-car-style="premium_automotive_vector_v5_side" data-car-layer="primary"><ellipse cx="760" cy="640" rx="670" ry="68" fill="#000" opacity=".75" filter="url(#shadow)"/><path d="M80 525 Q118 430 295 386 L488 315 Q620 258 796 274 L966 296 Q1088 312 1204 382 L1395 482 Q1450 514 1460 555 L1415 607 L1130 620 L340 632 L122 598 L72 557 Z" fill="url(#body)" stroke="#F7F8FA" stroke-width="6"/><path d="M302 385 L490 220 Q575 155 717 160 L882 180 Q1014 196 1136 322 L1182 388 L930 402 L520 404 Z" fill="url(#glass)" stroke="#B8C6D0" stroke-width="5"/><path d="M505 225 L535 400 M865 184 L930 400" stroke="#C0CBD3" stroke-width="4" opacity=".75"/><path d="M116 500 Q365 405 610 420 Q916 421 1210 448 L1405 518" fill="none" stroke="#FFFFFF" stroke-opacity=".52" stroke-width="9"/><path d="M145 532 Q395 474 645 480 L1145 485 Q1305 490 1418 529" fill="none" stroke="{ACCENT}" stroke-opacity=".90" stroke-width="5"/><path d="M1185 400 L1378 488 L1450 532 L1398 560 L1268 536 L1140 470 Z" fill="#141B22"/><path d="M1310 490 L1440 528 L1402 554 L1317 542 Z" fill="#C9342E"/><path d="M110 536 L276 512 L305 568 L136 578 Z" fill="#202A34"/><path d="M220 585 Q660 621 1272 568" fill="none" stroke="#070A0D" stroke-width="14"/><path d="M435 356 Q692 326 1038 358" fill="none" stroke="#FFFFFF" stroke-opacity=".16" stroke-width="11"/>{_wheel(350,584,int(110*wheel_scale))}{_wheel(1120,566,int(110*wheel_scale))}</g>'''
def _car_front(transform:str="") -> str:
    return f'''<g transform="{transform}" data-car-style="premium_automotive_vector_v5_front" data-car-layer="primary"><ellipse cx="960" cy="870" rx="540" ry="48" fill="#000" opacity=".72" filter="url(#shadow)"/><path d="M420 690 Q430 430 560 350 Q690 265 960 250 Q1230 265 1360 350 Q1490 430 1500 690 L1370 820 Q960 920 550 820 Z" fill="url(#body)" stroke="#F7F8FA" stroke-width="7"/><path d="M600 380 Q760 286 960 282 Q1160 286 1320 380 L1270 535 L650 535 Z" fill="url(#glass)" stroke="#BAC7D0" stroke-width="5"/><path d="M665 595 Q960 535 1255 595 L1325 760 Q960 875 595 760 Z" fill="#111820" stroke="#73808B" stroke-width="5"/><path d="M735 650 Q960 590 1185 650 L1125 790 Q960 820 795 790 Z" fill="#050709" stroke="{ACCENT}" stroke-width="6"/><path d="M515 585 L700 625 L680 700 L515 670 Z M1405 585 L1220 625 L1240 700 L1405 670 Z" fill="#ECEEF0"/><path d="M520 470 Q960 390 1400 470" fill="none" stroke="#FFFFFF" stroke-opacity=".18" stroke-width="10"/>{_wheel(585,770,98)}{_wheel(1335,770,98)}</g>'''
def _car_rear(transform:str="") -> str:
    return f'''<g transform="{transform}" data-car-style="premium_automotive_vector_v5_rear" data-car-layer="primary"><ellipse cx="960" cy="870" rx="540" ry="48" fill="#000" opacity=".72" filter="url(#shadow)"/><path d="M420 650 Q445 470 575 360 Q715 255 960 250 Q1205 255 1345 360 Q1475 470 1500 650 L1415 805 Q960 900 505 805 Z" fill="url(#body)" stroke="#F7F8FA" stroke-width="7"/><path d="M610 380 Q760 286 960 282 Q1160 286 1310 380 L1278 520 L642 520 Z" fill="url(#glass)" stroke="#BAC7D0" stroke-width="5"/><path d="M530 585 Q960 535 1390 585 L1430 720 Q960 840 490 720 Z" fill="#182028"/><path d="M535 610 Q730 550 810 610 L770 700 Q650 725 545 690 Z M1385 610 Q1190 550 1110 610 L1150 700 Q1270 725 1375 690 Z" fill="#C9342E"/><path d="M780 650 H1140 V760 H780 Z" fill="#090D12" stroke="#6D7882" stroke-width="5"/><rect x="880" y="676" width="160" height="48" rx="8" fill="#2B333B"/>{_wheel(575,770,98)}{_wheel(1345,770,98)}</g>'''
def _car_high(transform:str="") -> str:
    return f'''<g transform="{transform}" data-car-style="premium_automotive_vector_v5_high" data-car-layer="primary"><ellipse cx="960" cy="620" rx="620" ry="55" fill="#000" opacity=".7" filter="url(#shadow)"/><path d="M280 600 Q350 425 550 325 Q760 220 960 215 Q1160 220 1370 325 Q1570 425 1640 600 Q1550 780 1260 855 Q960 930 660 855 Q370 780 280 600 Z" fill="url(#body)" stroke="#F7F8FA" stroke-width="7"/><path d="M520 455 Q680 315 960 300 Q1240 315 1400 455 L1310 610 Q960 690 610 610 Z" fill="url(#glass)" stroke="#AEBCC7" stroke-width="6"/><path d="M360 635 Q960 780 1560 635" fill="none" stroke="{ACCENT}" stroke-width="7" opacity=".8"/><path d="M450 585 L600 520 M1470 585 L1320 520" stroke="#FFF" stroke-opacity=".25" stroke-width="12"/>{_wheel(525,720,105)}{_wheel(1395,720,105)}</g>'''
def _interior_primary(transform:str="") -> str:
    return f'''<g transform="{transform}" data-car-style="premium_automotive_vector_v5_interior" data-car-layer="primary"><rect x="0" y="0" width="850" height="620" rx="36" fill="#0A0E13" stroke="#57636E" stroke-width="6"/><path d="M75 470 L175 235 Q290 170 445 185 L760 270 L785 480 Z" fill="#202A34" stroke="#A7B4BE" stroke-width="5"/><rect x="250" y="115" width="330" height="125" rx="22" fill="#05080C" stroke="{ACCENT}" stroke-width="7"/><path d="M280 355 Q345 275 445 320 L465 535 H250 Z M575 320 Q675 275 740 355 L770 535 H555 Z" fill="#121920" stroke="#9AA6AF" stroke-width="5"/><circle cx="675" cy="245" r="70" fill="#090D12" stroke="{ACCENT}" stroke-width="7"/><path d="M675 205 L675 285 M635 245 H715" stroke="#CED6DC" stroke-width="6"/><text x="55" y="575" font-family="Noto Sans" font-size="24" fill="{MUTED}">CABIN / DRIVER INTERFACE</text></g>'''
def _wheel_primary(transform:str="") -> str:
    return f'''<g transform="{transform}" data-car-style="premium_automotive_vector_v5_wheel" data-car-layer="primary"><circle cx="960" cy="550" r="330" fill="#030507" stroke="#E3E9ED" stroke-width="16"/><circle cx="960" cy="550" r="255" fill="#808B95"/><circle cx="960" cy="550" r="195" fill="#11171D" stroke="#56626C" stroke-width="8"/>{''.join(f'<path d="M960 550 L960 375" stroke="#C4CCD2" stroke-width="12" transform="rotate({a} 960 550)"/>' for a in (0,45,90,135,180,225,270,315))}<circle cx="960" cy="550" r="38" fill="{ACCENT}"/><path d="M760 705 Q960 760 1160 705" fill="none" stroke="#C9342E" stroke-width="16"/><text x="720" y="875" font-family="Noto Sans" font-size="26" fill="{MUTED}">BRAKE / WHEEL DETAIL</text></g>'''
def _battery_primary(transform:str="") -> str:
    return f'''<g transform="{transform}" data-car-style="premium_automotive_vector_v5_battery" data-car-layer="primary"><path d="M180 560 Q250 360 540 310 H1380 Q1670 360 1740 560 L1600 720 H320 Z" fill="#202A34" stroke="#BAC6CE" stroke-width="7"/><rect x="430" y="465" width="1060" height="185" rx="24" fill="#111820" stroke="{ACCENT}" stroke-width="8"/><g>{''.join(f'<rect x="{470+i*115}" y="500" width="85" height="115" rx="10" fill="#27333D" stroke="#7D8993" stroke-width="3"/>' for i in range(8))}</g><text x="430" y="755" font-family="Noto Sans" font-size="28" fill="{MUTED}">BATTERY PACK / ENERGY MODULE</text></g>'''
def _charge_primary(transform:str="") -> str:
    return f'''<g transform="{transform}" data-car-style="premium_automotive_vector_v5_charge" data-car-layer="primary"><path d="M330 690 Q420 390 700 300 Q1080 180 1420 330 Q1580 420 1660 690" fill="url(#body)" stroke="#F7F8FA" stroke-width="8"/><path d="M530 360 Q960 220 1390 380" fill="none" stroke="#BAC7D0" stroke-width="6"/><circle cx="1360" cy="470" r="86" fill="#080C11" stroke="{ACCENT}" stroke-width="10"/><path d="M1335 430 L1390 430 L1370 470 L1415 470 L1345 535 L1360 485 L1318 485 Z" fill="#F4C76B"/><path d="M470 620 Q960 700 1490 620" fill="none" stroke="#5D6872" stroke-width="8"/><text x="1210" y="355" font-family="Noto Sans" font-size="24" fill="{MUTED}">CHARGE PORT</text></g>'''
def _aero_primary(transform:str="") -> str:
    return f'''<g transform="{transform}" data-car-style="premium_automotive_vector_v5_aero" data-car-layer="primary">{_car_front("scale(.95)")}<path d="M505 790 Q960 910 1415 790" fill="none" stroke="{ACCENT}" stroke-width="18"/><path d="M410 835 H1510" stroke="#6B7782" stroke-width="5"/><text x="760" y="900" font-family="Noto Sans" font-size="26" fill="{MUTED}">AERO / AIRFLOW</text></g>'''
def _vehicle_primary(family:str,transform:str="")->str:
    if family=="front_close": return _car_front(transform)
    if family in {"rear_3q","rear_close"}: return _car_rear(transform)
    if family in {"wide_scene","three_quarter_high"}: return _car_high(transform)
    if family=="interior": return _interior_primary("translate(1030 205) scale(.78)")
    if family=="wheel_detail": return _wheel_primary("translate(350 40) scale(.82)")
    if family=="battery": return _battery_primary("translate(70 120) scale(.86)")
    if family=="charging": return _charge_primary("translate(45 115) scale(.87)")
    if family=="aero": return _aero_primary(transform)
    if family=="performance": return _car_front(transform)
    if family=="safety": return _car_front(transform)
    if family=="technology": return _car_high(transform)
    if family=="design_detail": return _car_front(transform)
    return _car(transform)

def _card(value:str,x:int,y:int,width:int=455)->str:return f'<rect x="{x}" y="{y}" width="{width}" height="92" rx="18" fill="{PANEL}" fill-opacity=".94" stroke="#3A4652"/>{_text(value,x+26,y+58,24,650,"start",TEXT)}<circle cx="{x+width-28}" cy="{y+46}" r="7" fill="{ACCENT}"/>'
def _focus(family:str,scene)->str:
    calls=[str(c).strip() for c in scene.callouts if str(c).strip()];cards=''.join(_card(c,1370,200+i*112,455) for i,c in enumerate(calls[:3]))
    if family=="wheel_detail": return ''
    if family in {"technology","battery","charging","safety"}:
        label={"technology":"SYSTEM ARCHITECTURE","battery":"BATTERY / ENERGY","charging":"CHARGING FLOW","safety":"SAFETY COVERAGE"}[family];dots=''.join(f'<circle cx="{1440+i*120}" cy="720" r="18" fill="{ACCENT}"/>' for i in range(4));return f'<path d="M1380 720 H1800" stroke="{LINE}" stroke-width="6"/>{dots}{_text(label,1380,790,20,700,"start",MUTED)}<path d="M1420 665 L1530 610 L1640 650 L1740 570 L1810 595" fill="none" stroke="{ACCENT}" stroke-width="7"/>{cards}'
    if family=="performance":return f'<path d="M1380 760 H1810" stroke="{LINE}" stroke-width="10"/><path d="M1380 760 L1510 735 L1615 680 L1715 615 L1810 590" fill="none" stroke="{ACCENT}" stroke-width="9"/>{_text("PERFORMANCE RESPONSE",1380,820,20,700,"start",MUTED)}{cards}'
    if family=="comparison":return f'<rect x="1365" y="220" width="470" height="535" rx="24" fill="{PANEL}" fill-opacity=".92" stroke="#3A4652"/>{_text("POSITION IN CLASS",1400,270,19,700,"start",MUTED)}<path d="M1420 350 H1780 M1420 480 H1780 M1420 610 H1780" stroke="#3A4652" stroke-width="3"/><path d="M1420 350 H1660 M1420 480 H1710 M1420 610 H1600" stroke="{ACCENT}" stroke-width="14" stroke-linecap="round"/>'
    label={"design_detail":"DESIGN DETAIL","front_close":"FRONT DETAIL","rear_close":"REAR DETAIL","aero":"AERODYNAMICS"}.get(family,"AUTOMOTIVE EDITORIAL");return f'<path d="M1380 790 Q1540 650 1810 720" fill="none" stroke="{ACCENT}" stroke-width="7"/><circle cx="1590" cy="700" r="13" fill="{ACCENT}"/>{_text(label,1380,845,20,700,"start",MUTED)}{cards}'

def render_scene_svg(scene,topic:str,out:Path)->None:
    family=_family(scene,_kind(scene));kind=_kind(scene);motion=_motion(family,int(scene.id));intent=str(scene.visual_intent).strip();calls=[str(c).strip() for c in scene.callouts if str(c).strip()];transforms={"front_3q":"translate(40 205) scale(.94)","low_angle":"translate(-40 260) scale(1.02)","front_close":"translate(70 60) scale(.72)","rear_3q":"translate(300 95) scale(.74)","wide_scene":"translate(120 80) scale(.72)","three_quarter_high":"translate(120 85) scale(.78)","side_profile":"translate(60 255) scale(.84)","rear_close":"translate(300 75) scale(.74)","design_detail":"translate(80 130) scale(.84)","aero":"translate(25 80) scale(.72)","wheel_detail":"","interior":"","technology":"translate(120 80) scale(.76)","safety":"translate(80 70) scale(.72)","battery":"","charging":"","performance":"translate(70 70) scale(.72)","comparison":"translate(40 240) scale(.88)"}
    car=_vehicle_primary(family,transforms.get(family,"translate(40 205) scale(.94)"));focus=_focus(family,scene);topic_x=1810 if _has_arabic(topic) else 70
    if family=="interior":focus=''.join(_card(c,1110,760+i*112,700) for i,c in enumerate(calls[:2]))
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}" data-visual-family="{family}" data-visual-mode="{kind}" data-layout="{_safe(scene.layout,40)}" data-camera-angle="{family}" data-visual-intent="{_safe(intent,240)}" data-motion="{motion}" data-car-layer="primary" data-asset-quality="premium_automotive_editorial_v5">{_defs()}{_environment(int(scene.id))}<path d="M70 105 H1850" stroke="{ACCENT}" stroke-width="3" opacity=".75"/>{_text(topic,topic_x,75,28,700,"start",TEXT)}{car}{focus}{_text(kind.upper(),70,985,18,700,"start",MUTED)}</svg>'''
    out.parent.mkdir(parents=True,exist_ok=True);out.write_text(svg,encoding="utf-8")

def generate_visuals(story:Story,out_dir:Path=RUN/"scenes")->None:
    out_dir.mkdir(parents=True,exist_ok=True)
    for scene in story.scenes:render_scene_svg(scene,story.topic,out_dir/f"scene_{scene.id:02d}.svg")
